mkdir -p /tmp/probe && cat > /tmp/probe/enc.mjs <<'EOF'
const CH="qpzry9x8gf2tvdw0s3jn54khce6mua7l";
const GEN=[0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3];
const B32=1, B32M=0x2bc830a3;
function pm(v){let c=1;for(const p of v){const b=c>>25;c=((c&0x1ffffff)<<5)^p;for(let i=0;i<5;i++)if((b>>i)&1)c^=GEN[i];}return c;}
function hrpExp(h){const a=[],b=[];for(const c of h){a.push(c.charCodeAt(0)>>5);b.push(c.charCodeAt(0)&31);}return a.concat([0],b);}
function mkChk(h,d,spec){const v=hrpExp(h).concat(d,[0,0,0,0,0,0]);const p=pm(v)^spec;const r=[];for(let i=0;i<6;i++)r.push((p>>(5*(5-i)))&31);return r;}
function enc(h,d,spec){const c=mkChk(h,d,spec);return h+"1"+d.concat(c).map(x=>CH[x]).join("");}
function conv(data,from,to,pad){let acc=0,bits=0;const ret=[],maxv=(1<<to)-1,maxacc=(1<<(from+to-1))-1;
for(const v of data){if(v<0||(v>>from)!==0)return null;acc=((acc<<from)|v)&maxacc;bits+=from;while(bits>=to){bits-=to;ret.push((acc>>bits)&maxv);}}
if(pad){if(bits)ret.push((acc<<(to-bits))&maxv);}else if(bits>=from||((acc<<(to-bits))&maxv))return null;return ret;}
function segwit(hrp,ver,prog,spec){return enc(hrp,[ver].concat(conv(prog,8,5,true)),spec);}
const prog20=[];for(let i=0;i<20;i++)prog20.push((i*7+3)&255);
const prog32=[];for(let i=0;i<32;i++)prog32.push((i*11+5)&255);
const prog2=[1,2], prog40=[];for(let i=0;i<40;i++)prog40.push((i*3+1)&255);
const out=[];
for(const ver of [0,1,2,16,17]){
  for(const [pn,prog] of [["p20",prog20],["p32",prog32],["p2",prog2],["p40",prog40]]){
    for(const [sn,spec] of [["bech32",B32],["bech32m",B32M]]){
      out.push([`v${ver}/${pn}/${sn}`, segwit("bc",ver,prog,spec)]);
    }
  }
}
console.log(out.map(x=>x.join(" ")).join("\n"));
EOF
