// Bech32 base-32 alphabet and character helpers.

/** The Bech32 character set used for the data part of an address. */
export const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";

/** The character separating the human-readable part from the data part. */
export const SEPARATOR = "1";

/** Longest human-readable part accepted by this implementation. */
export const MAX_HRP_LENGTH = 83;

/** Number of Bech32 characters occupied by the trailing checksum. */
export const CHECKSUM_LENGTH = 6;

/**
 * Position of `ch` in CHARSET, or -1 when the character is not a Bech32 digit.
 */
export function charsetIndex(ch) {
  return CHARSET.indexOf(ch);
}

/**
 * True when every code point of `text` is a printable US-ASCII character,
 * i.e. in the inclusive range 33..126.
 */
export function isPrintableAscii(text) {
  for (const ch of text) {
    const code = ch.codePointAt(0);
    if (code < 33 || code > 126) {
      return false;
    }
  }
  return true;
}

/**
 * True when `text` mixes upper and lower case letters. A string that is
 * entirely lower case or entirely upper case is not considered mixed.
 */
export function hasMixedCase(text) {
  return text.toLowerCase() !== text && text.toUpperCase() !== text;
}

