 * never exceeds 2^30, so plain 32-bit bitwise arithmetic is exact here.
 */
export function polymod(values) {
  let chk = 1;
  for (const value of values) {
    const top = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ value;
    for (let i = 0; i < 5; i++) {
      if ((top >> i) & 1) {
        chk ^= GENERATOR[i];
      }
    }
  }
  return chk;
}

/**
 * Expand the human-readable part into the 5-bit values that seed the
 * checksum: the high bits of every character, a zero, then the low bits.
 */
export function hrpExpand(hrp) {
  const high = [];
  const low = [];
  for (const ch of hrp) {
    const code = ch.codePointAt(0);
    high.push(code >> 5);
    low.push(code & 31);
  }
  return high.concat([0], low);
}

/**
 * Verify that `data` (payload followed by its 6 checksum values) carries a
 * valid Bech32 checksum for `hrp`.
 */
export function verifyChecksum(hrp, data) {
  return polymod(hrpExpand(hrp).concat(data)) === BECH32_CONST;
}

