// General power-of-2 base conversion shared by the Bech32 codecs.

/**
 * Regroup `data` from `fromBits`-wide values into `toBits`-wide values.
 *
 * With `pad` set, a trailing partial group is zero-extended. Without it, a
 * trailing group is only tolerated when it is shorter than a source value and
 * carries no set bits; otherwise the input is rejected. Returns null when the
 * input cannot be converted.
 */
export function convertBits(data, fromBits, toBits, pad) {
  let acc = 0;
  let bits = 0;
  const ret = [];
  const maxv = (1 << toBits) - 1;
  const maxAcc = (1 << (fromBits + toBits - 1)) - 1;

  for (const value of data) {
    if (value < 0 || value >> fromBits) {
      return null;
    }
    acc = ((acc << fromBits) | value) & maxAcc;
    bits += fromBits;
    while (bits >= toBits) {
      bits -= toBits;
      ret.push((acc >> bits) & maxv);
    }
  }

  if (pad) {
    if (bits) {
      ret.push((acc << (toBits - bits)) & maxv);
    }
  } else if (bits >= fromBits || ((acc << (toBits - bits)) & maxv)) {
    return null;
  }
  return ret;
