// Low-level Bech32 string validation: splits a string into its human-readable
// part and its 5-bit data payload.

import {
  CHECKSUM_LENGTH,
  MAX_HRP_LENGTH,
  SEPARATOR,
  charsetIndex,
  hasMixedCase,
  isPrintableAscii,
} from "./charset.mjs";
import { verifyChecksum } from "./checksum.mjs";

/**
 * Validate a Bech32 string and split it up.
 *
 * Returns `{ hrp, data }` where `hrp` is the lower-cased human-readable part
 * and `data` is the list of 5-bit payload values with the checksum stripped.
 * Returns `{ hrp: null, data: null }` for any invalid input.
 */
export function bech32Decode(bech) {
  if (!isPrintableAscii(bech) || hasMixedCase(bech)) {
    return { hrp: null, data: null };
  }

  const lowered = bech.toLowerCase();
  const pos = lowered.lastIndexOf(SEPARATOR);
  if (
    pos < 1 ||
    pos > MAX_HRP_LENGTH ||
    pos + 1 + CHECKSUM_LENGTH > lowered.length
  ) {
    return { hrp: null, data: null };
  }

  const dataPart = lowered.slice(pos + 1);
  const data = [];
  for (const ch of dataPart) {
    const index = charsetIndex(ch);
    if (index < 0) {
      return { hrp: null, data: null };
    }
    data.push(index);
  }

  const hrp = lowered.slice(0, pos);
  if (!verifyChecksum(hrp, data)) {
    return { hrp: null, data: null };
  }
  return { hrp, data: data.slice(0, data.length - CHECKSUM_LENGTH) };
}

