// SegWit address decoding (BIP173 layout) on top of the Bech32 primitives.

import { bech32Decode } from "./bech32.mjs";
import { convertBits } from "./convertbits.mjs";

/** Highest witness version that can be expressed in a SegWit address. */
export const MAX_WITNESS_VERSION = 16;

/** Inclusive bounds on the witness program length, in bytes. */
export const MIN_PROGRAM_LENGTH = 2;
export const MAX_PROGRAM_LENGTH = 40;

/** Witness program lengths allowed for version 0 (P2WPKH and P2WSH). */
const V0_PROGRAM_LENGTHS = [20, 32];

/**
 * Decode a SegWit address for the expected human-readable part `hrp`.
 *
 * Returns `[witnessVersion, program]` on success, where `program` is a list of
 * byte values, and `[null, null]` when the address is not a valid SegWit
 * address under `hrp`.
 */
export function decode(hrp, addr) {
  const { hrp: hrpGot, data } = bech32Decode(addr);
  if (hrpGot !== hrp) {
    return [null, null];
  }

  const decoded = convertBits(data.slice(1), 5, 8, false);
  if (
    decoded === null ||
    decoded.length < MIN_PROGRAM_LENGTH ||
    decoded.length > MAX_PROGRAM_LENGTH
  ) {
    return [null, null];
  }
  if (data[0] > MAX_WITNESS_VERSION) {
    return [null, null];
  }
  if (data[0] === 0 && !V0_PROGRAM_LENGTHS.includes(decoded.length)) {
    return [null, null];
  }
  return [data[0], decoded];
}

