// Rendering of values in Python's `print` / `repr` notation.

/** Marker for a Python tuple, which renders with parentheses rather than brackets. */
class PyTuple {
  constructor(items) {
    this.items = items;
  }
}

/** Wrap values so that `pyRepr` renders them as a Python tuple. */
export function tuple(...items) {
  return new PyTuple(items);
}

/**
 * Render `value` the way CPython's `repr` would. `print` of a container uses
 * the same notation, so this doubles as the formatter for program output.
 */
export function pyRepr(value) {
  if (value === null || value === undefined) {
    return "None";
  }
  if (value instanceof PyTuple) {
    const parts = value.items.map(pyRepr);
    // A one-element tuple keeps its trailing comma.
    return parts.length === 1 ? `(${parts[0]},)` : `(${parts.join(", ")})`;
  }
  if (Array.isArray(value)) {
    return `[${value.map(pyRepr).join(", ")}]`;
  }
  if (typeof value === "boolean") {
    return value ? "True" : "False";
  }
  if (typeof value === "number") {
    return Number.isInteger(value) ? String(value) : String(value);
  }
  return `'${String(value).replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
}

/** Print `value` exactly as Python's `print(value)` would. */
export function pyPrint(value) {
  console.log(pyRepr(value));
}

