import { fileURLToPath } from "node:url";

import { ArgumentParser } from "./lib/argparser.mjs";
import { decode } from "./lib/segwit.mjs";
import { pyPrint, tuple } from "./lib/pyrepr.mjs";

function main() {
  const parser = new ArgumentParser();
  parser.addArgument(["--a"], { required: true }); // HRP
  parser.addArgument(["--b"], { required: true }); // Segwit address
  const args = parser.parseArgs();

  const result = decode(args.a, args.b); // Decode segwit address
  pyPrint(tuple(...result));
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  main();
}

export { main };

