// A small, faithful subset of Python's `argparse`: option abbreviation,
// `--opt=value` syntax, the `--` separator, required-argument checking, and
// argparse's exact usage/help/error rendering and exit codes.

import { basename } from "node:path";

/** Values matching this are treated as data, not as unknown options. */
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

/** Column at which argparse stops aligning help text. */
const MAX_HELP_POSITION = 24;

/** argparse indents each option entry by two spaces. */
const INDENT = "  ";

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog ?? basename(process.argv[1] ?? "");
    this.actions = [];
    this.optionStrings = new Map();
    this.addArgument(["-h", "--help"], {
      kind: "help",
      help: "show this help message and exit",
    });
  }

  /**
   * Register an option. `kind` is "store" (consumes one value) or "help".
   * `metavar` defaults to argparse's upper-cased destination name.
   */
  addArgument(flags, { kind = "store", required = false, help = null, metavar } = {}) {
    const dest = flags[flags.length - 1].replace(/^-+/, "");
    const action = {
      optionStrings: flags,
      dest,
      kind,
      required,
      help,
      metavar: metavar ?? dest.toUpperCase(),
    };
    this.actions.push(action);
    for (const flag of flags) {
      this.optionStrings.set(flag, action);
    }
    return action;
  }

  /** How an option appears inside the usage line, e.g. `--a A`. */
  #formatInvocationShort(action) {
    const flag = action.optionStrings[0];
    return action.kind === "store" ? `${flag} ${action.metavar}` : flag;
  }

  /** How an option appears in the options list, e.g. `-h, --help`. */
  #formatInvocationLong(action) {
    if (action.kind !== "store") {
      return action.optionStrings.join(", ");
    }
    return action.optionStrings.map((flag) => `${flag} ${action.metavar}`).join(", ");
  }

  formatUsage() {
    const parts = this.actions.map((action) => {
      const invocation = this.#formatInvocationShort(action);
      return action.required ? invocation : `[${invocation}]`;
    });
    return `usage: ${this.prog}${parts.length ? " " + parts.join(" ") : ""}\n`;
  }

  formatHelp() {
    const invocations = this.actions.map((action) => this.#formatInvocationLong(action));
    const maxLength = Math.max(...invocations.map((text) => text.length + INDENT.length));
    const helpPosition = Math.min(maxLength + 2, MAX_HELP_POSITION);

    const lines = [];
    this.actions.forEach((action, index) => {
      const invocation = INDENT + invocations[index];
      if (action.help === null) {
        lines.push(invocation);
      } else if (invocation.length < helpPosition) {
        lines.push(invocation.padEnd(helpPosition) + action.help);
      } else {
        lines.push(invocation, " ".repeat(helpPosition) + action.help);
      }
    });
    return `${this.formatUsage()}\noptions:\n${lines.join("\n")}\n`;
  }

  printHelp() {
    process.stdout.write(this.formatHelp());
  }

  /** Report a usage error the way argparse does, then exit with status 2. */
  error(message) {
    process.stderr.write(this.formatUsage());
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  /** True when any registered flag itself looks like a negative number. */
  get #hasNegativeNumberOptionals() {
    for (const flag of this.optionStrings.keys()) {
      if (NEGATIVE_NUMBER.test(flag)) {
        return true;
      }
    }
    return false;
  }

  /** Options whose name starts with the given (possibly abbreviated) string. */
  #optionTuples(argString) {
    const matches = [];
    if (argString.startsWith("--")) {
      let prefix = argString;
      let explicitArg = null;
      const eq = argString.indexOf("=");
      if (eq >= 0) {
        prefix = argString.slice(0, eq);
        explicitArg = argString.slice(eq + 1);
      }
      for (const [flag, action] of this.optionStrings) {
        if (flag.startsWith(prefix)) {
          matches.push({ action, optionString: flag, explicitArg });
        }
      }
      return matches;
    }
    const shortFlag = argString.slice(0, 2);
    const shortArg = argString.slice(2);
    for (const [flag, action] of this.optionStrings) {
      if (flag === shortFlag) {
        matches.push({ action, optionString: flag, explicitArg: shortArg });
      } else if (flag.startsWith(argString)) {
        matches.push({ action, optionString: flag, explicitArg: null });
      }
    }
    return matches;
  }

  /**
   * Classify one argument. Returns null when it is a plain value, otherwise a
   * tuple whose `action` is null for an unrecognized option.
   */
  #parseOptional(argString) {
    if (!argString || argString[0] !== "-") {
      return null;
    }
    if (this.optionStrings.has(argString)) {
      return { action: this.optionStrings.get(argString), optionString: argString, explicitArg: null };
    }
    if (argString.length === 1) {
      return null;
    }
    const eq = argString.indexOf("=");
    if (eq >= 0) {
      const optionString = argString.slice(0, eq);
      if (this.optionStrings.has(optionString)) {
        return {
          action: this.optionStrings.get(optionString),
          optionString,
          explicitArg: argString.slice(eq + 1),
        };
      }
    }
    const matches = this.#optionTuples(argString);
    if (matches.length > 1) {
      const names = matches.map((match) => match.optionString).join(", ");
      this.error(`ambiguous option: ${argString} could match ${names}`);
    }
    if (matches.length === 1) {
      return matches[0];
    }
    if (NEGATIVE_NUMBER.test(argString) && !this.#hasNegativeNumberOptionals) {
      return null;
    }
    if (argString.includes(" ")) {
      return null;
    }
    return { action: null, optionString: argString, explicitArg: null };
  }

  /** Parse, tolerating unknown arguments; returns the namespace plus extras. */
  parseKnownArgs(argv) {
    // First pass: label every argument as an option ("O"), a value ("A"), or
    // the "--" separator, so option handling can tell whether a value follows.
    const pattern = [];
    const tuples = new Map();
    for (let i = 0; i < argv.length; i++) {
      if (argv[i] === "--") {
        pattern.push("-");
        while (++i < argv.length) {
          pattern.push("A");
        }
        break;
      }
      const tuple = this.#parseOptional(argv[i]);
      if (tuple === null) {
        pattern.push("A");
      } else {
        tuples.set(i, tuple);
        pattern.push("O");
      }
    }

    const namespace = {};
    for (const action of this.actions) {
      if (action.kind === "store") {
        namespace[action.dest] = null;
      }
    }

    const extras = [];
    const seen = new Set();
    for (let i = 0; i < argv.length; i++) {
      if (pattern[i] === "-") {
        continue; // the "--" separator is consumed, never reported
      }
      if (pattern[i] === "A") {
        extras.push(argv[i]);
        continue;
      }
      const { action, optionString, explicitArg } = tuples.get(i);
      if (action === null) {
        extras.push(argv[i]);
        continue;
      }
      if (action.kind === "help") {
        this.printHelp();
        process.exit(0);
      }
      let value;
      if (explicitArg !== null) {
        value = explicitArg;
      } else if (pattern[i + 1] === "A") {
        value = argv[++i];
      } else {
        this.error(`argument ${optionString}: expected one argument`);
      }
      namespace[action.dest] = value;
      seen.add(action);
    }

    const missing = this.actions
      .filter((action) => action.required && !seen.has(action))
      .map((action) => action.optionStrings[0]);
    if (missing.length) {
      this.error(`the following arguments are required: ${missing.join(", ")}`);
    }
    return { namespace, extras };
  }

  /** Parse, rejecting unknown arguments. */
  parseArgs(argv = process.argv.slice(2)) {
    const { namespace, extras } = this.parseKnownArgs(argv);
    if (extras.length) {
      this.error(`unrecognized arguments: ${extras.join(" ")}`);
    }
    return namespace;
  }
}

